solution.solution.cpp:
int digitSum(int n)
{
    int total{ 0 };
    while (n > 0)
    {
        total += n % 10;
        n /= 10;
    }
    return total;
}

unitTests:
TEST("three digits") { CHECK_EQ(digitSum(472), 13); }
TEST("single digit") { CHECK_EQ(digitSum(7), 7); CHECK_EQ(digitSum(0), 0); }
TEST("many digits") { CHECK_EQ(digitSum(999999), 54); CHECK_EQ(digitSum(1000000), 1); }

